import{_ as e,C as o,c as a,o as s,j as t,G as r,a0 as i,b as n,a as l,w as d,a1 as m}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Definição de metas para jogadores de petanca","description":"","frontmatter":{},"headers":[],"relativePath":"pt/education/goals/index.md","filePath":"pt/education/goals/index.md"}');const c=e({name:"pt/education/goals/index.md"},[["render",function(e,u,c,p,h,q){const g=o("AdBanner"),b=o("Mermaid"),v=o("AdInArticle");return s(),a("div",null,[u[1]||(u[1]=t("h1",{id:"definicao-de-metas-para-jogadores-de-petanca",tabindex:"-1"},[l("Definição de metas para jogadores de petanca "),t("a",{class:"header-anchor",href:"#definicao-de-metas-para-jogadores-de-petanca","aria-label":'Permalink to "Definição de metas para jogadores de petanca"'},"​")],-1)),r(g),u[2]||(u[2]=i('<p>Metas claras são a sua bússola. Elas dão direção ao seu treinamento, motivação quando as coisas ficam difíceis e uma maneira de medir o progresso. Sem metas, você está apenas jogando bolinhas. Com metas, você está construindo algo.</p><div class="tip custom-block"><p class="custom-block-title">O princípio fundamental</p><p><strong>Um objetivo sem um plano é apenas um desejo.</strong> Defina metas claras, divida-as em etapas menores, concentre-se no que você controla e acompanhe seu progresso.</p></div><h2 id="por-que-as-metas-sao-importantes" tabindex="-1">Por que as metas são importantes <a class="header-anchor" href="#por-que-as-metas-sao-importantes" aria-label="Permalink to &quot;Por que as metas são importantes&quot;">​</a></h2><p>Os objetivos servem a múltiplos propósitos:</p><ul><li><strong>Instruções:</strong> Saiba em que trabalhar</li><li><strong>Motivação:</strong> Ter algo pelo qual lutar</li><li><strong>Medição:</strong> Acompanhe seu progresso</li><li><strong>Foco:</strong> Priorize seu tempo limitado</li></ul><p>Para o jogador autônomo, os objetivos são especialmente importantes. Sem um treinador para pressioná-lo, seus objetivos se tornam seu guia.</p><h2 id="os-tres-tipos-de-objetivos" tabindex="-1">Os três tipos de objetivos <a class="header-anchor" href="#os-tres-tipos-de-objetivos" aria-label="Permalink to &quot;Os três tipos de objetivos&quot;">​</a></h2><p>Nem todos os objetivos são iguais. Compreender os diferentes tipos ajuda você a definir objetivos melhores.</p><h3 id="_1-objetivos-de-resultado" tabindex="-1">1. Objetivos de Resultado <a class="header-anchor" href="#_1-objetivos-de-resultado" aria-label="Permalink to &quot;1. Objetivos de Resultado&quot;">​</a></h3><p><strong>O quê:</strong> O resultado final que você deseja <strong>Exemplo:</strong> &quot;Ganhar o campeonato regional&quot; <strong>Nível de controle:</strong> Baixo - depende dos oponentes, das condições e da sorte.</p><h3 id="_2-metas-de-desempenho" tabindex="-1">2. Metas de desempenho <a class="header-anchor" href="#_2-metas-de-desempenho" aria-label="Permalink to &quot;2. Metas de desempenho&quot;">​</a></h3><p><strong>O quê:</strong> Padrões de desempenho específicos <strong>Exemplo:</strong> &quot;Alcançar 80% de precisão nos exercícios de arremesso&quot; <strong>Nível de controle:</strong> Médio - depende principalmente de você</p><h3 id="_3-objetivos-do-processo" tabindex="-1">3. Objetivos do Processo <a class="header-anchor" href="#_3-objetivos-do-processo" aria-label="Permalink to &quot;3. Objetivos do Processo&quot;">​</a></h3><p><strong>O quê:</strong> Ações e comportamentos que você controla <strong>Exemplo:</strong> &quot;Completar minha rotina pré-arremesso em todos os lançamentos&quot; <strong>Nível de controle:</strong> Alto - totalmente a seu critério</p><h3 id="a-hierarquia-de-objetivos" tabindex="-1">A Hierarquia de Objetivos <a class="header-anchor" href="#a-hierarquia-de-objetivos" aria-label="Permalink to &quot;A Hierarquia de Objetivos&quot;">​</a></h3>',15)),(s(),n(m,null,{default:d(()=>[r(b,{id:"mermaid-71",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BObjetivo%20final%20%3Cbr%2F%3E%20O%20Sonho%5D%20--%3E%20B%5BMetas%20de%20desempenho%20%3Cbr%2F%3E%20Conquistas%5D%0A%20%20%20%20B%20--%3E%20C%5BObjetivos%20do%20Processo%20%3Cbr%2F%3E%20A%C3%A7%C3%B5es%20di%C3%A1rias%5D%0A%0A%20%20%20%20A2%5B%26quot%3BGanhar%20o%20Campeonato%20Regional%26quot%3B%5D%20--%3E%20B2%5B%26quot%3B80%25%20de%20precis%C3%A3o%20nos%20disparos%26quot%3B%5D%0A%20%20%20%20B2%20--%3E%20C2%5B%26quot%3BRotina%20completa%20antes%20da%20filmagem%20%3Cbr%2F%3E%20cada%20arremesso%26quot%3B%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B%20fill%3A%23fff9c4%0A%20%20%20%20style%20C%20fill%3A%23c8e6c9%0A%20%20%20%20style%20A2%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B2%20fill%3A%23fff9c4%0A%20%20%20%20style%20C2%20fill%3A%23c8e6c9%0A"})]),fallback:d(()=>[...u[0]||(u[0]=[l(" Loading... ",-1)])]),_:1})),u[3]||(u[3]=i('<div class="warning custom-block"><p class="custom-block-title">Principais conclusões</p><p><strong>Concentre a maior parte da sua atenção nas metas de processo.</strong> Elas são o que você controla e levam aos resultados que você deseja.</p><ul><li><strong>Objetivos de resultado:</strong> Baixo controle, alta motivação</li><li><strong>Objetivos de desempenho:</strong> Controle moderado, progresso mensurável</li><li><strong>Objetivos do processo:</strong> Alto controle, foco diário ← <strong>Foco aqui</strong></li></ul></div><h2 id="o-quadro-smart" tabindex="-1">O Quadro SMART <a class="header-anchor" href="#o-quadro-smart" aria-label="Permalink to &quot;O Quadro SMART&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Lista de verificação para metas SMART</p><p>Todo objetivo deve ser:</p><ul><li>✅ <strong>E</strong>specífico - Claro e bem definido</li><li>✅ <strong>M</strong>ensurável - Você pode acompanhar o progresso</li><li>✅ <strong>Alcançável</strong> - Desafiador, mas possível</li><li>✅ <strong>R</strong>elevante - Alinhado com sua visão geral</li><li>✅ **Com prazo definido - Possui uma data limite</li></ul></div>',3)),r(v),u[4]||(u[4]=i('<h3 id="s-especifico" tabindex="-1">S - Específico <a class="header-anchor" href="#s-especifico" aria-label="Permalink to &quot;S - Específico&quot;">​</a></h3><p>❌ &quot;Aprimore suas habilidades de tiro&quot; ✅ &quot;Melhorar minha precisão de acerto direto a 8 metros&quot;</p><h3 id="m-mensuravel" tabindex="-1">M - Mensurável <a class="header-anchor" href="#m-mensuravel" aria-label="Permalink to &quot;M - Mensurável&quot;">​</a></h3><p>❌ &quot;Atire com mais precisão&quot; ✅ &quot;Acerte pelo menos 24/30 no exercício de arremesso em escada&quot;</p><h3 id="a-atingivel" tabindex="-1">A - Atingível <a class="header-anchor" href="#a-atingivel" aria-label="Permalink to &quot;A - Atingível&quot;">​</a></h3><p>❌ &quot;Nunca erre um tiro&quot; (impossível) ✅ &quot;Aumentar a precisão em 10% ao longo de 8 semanas&quot; (desafiador, mas realista)</p><h3 id="r-relevante" tabindex="-1">R - Relevante <a class="header-anchor" href="#r-relevante" aria-label="Permalink to &quot;R - Relevante&quot;">​</a></h3><p>❌ &quot;Correr uma maratona&quot; (sem relação direta) ✅ &quot;Melhore o equilíbrio e a estabilidade para arremessos mais precisos&quot; (auxilia no seu jogo)</p><h3 id="t-temporal" tabindex="-1">T - Temporal <a class="header-anchor" href="#t-temporal" aria-label="Permalink to &quot;T - Temporal&quot;">​</a></h3><p>❌ &quot;Um dia eu vou melhorar&quot; ✅ &quot;Até 15 de março, eu terei alcançado...&quot;</p><h2 id="exemplos-de-gols-para-petanca" tabindex="-1">Exemplos de gols para petanca <a class="header-anchor" href="#exemplos-de-gols-para-petanca" aria-label="Permalink to &quot;Exemplos de gols para petanca&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tipo</th><th>Gol ruim</th><th>Meta SMART</th></tr></thead><tbody><tr><td>Resultado</td><td>&quot;Ganhe mais&quot;</td><td>&quot;Chegar às semifinais do Torneio de Primavera&quot;</td></tr><tr><td>Desempenho</td><td>&quot;Aponte melhor&quot;</td><td>&quot;Atingir 70% dos pontos a uma distância de 50 cm e 8 m&quot;</td></tr><tr><td>Processo</td><td>&quot;Pratique mais&quot;</td><td>&quot;Realize 3 sessões de treinamento focadas por semana&quot;</td></tr></tbody></table><h2 id="desmembrando-grandes-objetivos" tabindex="-1">Desmembrando Grandes Objetivos <a class="header-anchor" href="#desmembrando-grandes-objetivos" aria-label="Permalink to &quot;Desmembrando Grandes Objetivos&quot;">​</a></h2><p>Grandes objetivos podem parecer assustadores. Divida-os em partes menores:</p><h3 id="exemplo-quot-ganhar-o-campeonato-do-clube-daqui-a-12-meses-quot" tabindex="-1">Exemplo: &quot;Ganhar o Campeonato do Clube (daqui a 12 meses)&quot; <a class="header-anchor" href="#exemplo-quot-ganhar-o-campeonato-do-clube-daqui-a-12-meses-quot" aria-label="Permalink to &quot;Exemplo: &amp;quot;Ganhar o Campeonato do Clube (daqui a 12 meses)&amp;quot;&quot;">​</a></h3><p><strong>Objetivo anual:</strong> Vencer o campeonato do clube</p><p><strong>Metas trimestrais:</strong></p><ul><li>Q1: Melhorar a precisão dos disparos para 75%</li><li>Q2: Desenvolver uma rotina pré-teste consistente</li><li>Q3: Domine as situações de pressão</li><li>4º trimestre: Desempenho máximo e preparação para a competição</li></ul><p><strong>Metas mensais (1º trimestre):</strong></p><ul><li>Mês 1: Estabelecer a linha de base, identificar as fragilidades.</li><li>Mês 2: Foco na técnica de tiro</li><li>Mês 3: Adicione pressão ao treino de arremesso</li></ul><p><strong>Metas semanais (Mês 2):</strong></p><ul><li>Semana 1: 3 sessões de filmagem, análise de vídeo</li><li>Semana 2: Trabalhar na questão técnica identificada</li><li>Semana 3: Aumente a distância gradualmente</li><li>Semana 4: Avalie o progresso, ajuste o plano.</li></ul><h2 id="conectando-metas-ao-seu-quot-porque-quot" tabindex="-1">Conectando metas ao seu &quot;porquê&quot; <a class="header-anchor" href="#conectando-metas-ao-seu-quot-porque-quot" aria-label="Permalink to &quot;Conectando metas ao seu &amp;quot;porquê&amp;quot;&quot;">​</a></h2><p>Os objetivos funcionam melhor quando estão conectados a uma motivação mais profunda.</p><p>Pergunte a si mesmo:</p><ul><li>Por que eu quero alcançar isso?</li><li>O que isso significará para mim?</li><li>Como me sentirei quando tiver sucesso?</li><li>O que me motiva a melhorar?</li></ul><p>Anote suas respostas. Volte a elas quando a motivação diminuir.</p><h2 id="nesta-secao" tabindex="-1">Nesta seção <a class="header-anchor" href="#nesta-secao" aria-label="Permalink to &quot;Nesta seção&quot;">​</a></h2><ul><li><strong><a href="/en/education/goals/smart-goals">Metas SMART em Detalhe</a></strong> - Uma análise aprofundada da criação de metas eficazes</li><li><strong><a href="/en/education/goals/planning">Criando seu Plano de Treinamento</a></strong> - Transforme metas em ação</li></ul><h2 id="resumo-regras-para-definicao-de-metas" tabindex="-1">Resumo: Regras para definição de metas <a class="header-anchor" href="#resumo-regras-para-definicao-de-metas" aria-label="Permalink to &quot;Resumo: Regras para definição de metas&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Regra nº 1: A Regra de Controle</p><p><strong>Concentre-se nos objetivos de processo (aquilo que você controla) em vez dos objetivos de resultado.</strong> Os objetivos de processo levam a objetivos de desempenho, que por sua vez levam a objetivos de resultado.</p></div><div class="tip custom-block"><p class="custom-block-title">Regra nº 2: A Regra SMART</p><p><strong>Os objetivos devem ser Específicos, Mensuráveis, Atingíveis, Relevantes e Temporais.</strong> Metas vagas produzem resultados vagos. Metas SMART produzem progresso.</p></div><div class="tip custom-block"><p class="custom-block-title">Regra nº 3: A Regra de Quebra</p><p><strong>Grandes metas precisam de marcos trimestrais, mensais e semanais.</strong> Divida grandes objetivos em pequenas etapas práticas que você possa concluir esta semana.</p></div><div class="tip custom-block"><p class="custom-block-title">Regra nº 4: A Regra da Conexão</p><p><strong>Conecte seus objetivos ao seu &quot;porquê&quot; mais profundo.</strong> Quando a motivação diminui, o seu &quot;porquê&quot; é o que te mantém firme.</p></div><h2 id="ponto-chave" tabindex="-1">Ponto-chave <a class="header-anchor" href="#ponto-chave" aria-label="Permalink to &quot;Ponto-chave&quot;">​</a></h2><blockquote><p>Um objetivo sem um plano é apenas um desejo.</p></blockquote><p>Defina metas claras. Divida-as em etapas menores. Concentre-se no que você controla. Acompanhe seu progresso.</p>',37)),r(g)])}]]);export{u as __pageData,c as default};
